using Meziantou.Framework.Imaging.Internals;
using Meziantou.Framework.Imaging.Metadata;
using Meziantou.Framework.Imaging.TestHarness.Adapters;
using Meziantou.Framework.Imaging.TestHarness.Avif;
using Meziantou.Framework.Imaging.TestHarness.Fixtures;
using Meziantou.Framework.Imaging.TestHarness.Golden;
using Meziantou.Framework.Imaging.TestHarness.Pixels;

namespace Meziantou.Framework.Imaging.Tests.Conformance;

/// <summary>
/// AVIF decoding (still images and image sequences) against the corpus generated by
/// <c>tools/Meziantou.Framework.Imaging.CorpusGenerator/AvifCorpus.Container.cs</c>. The eager, sequential and identify suites
/// already compare every fixture under its policy; these tests compare what the library reports with the structure that the
/// independent reader (<see cref="ReferenceAvif"/>) finds in the bytes, check that the fixtures cover the container features,
/// that the samples no matrix applies to are exact, and pin the policy of each matrixed fixture to the measurement: one unit
/// and the measured mean error + 0.01 against the exact-rational reference (<c>LibraryAvifMeasurements</c> in the generator),
/// so that a numerical change of the color conversion is noticed and reviewed.
/// </summary>
public sealed class AvifDecoderConformanceTests
{
    public static TheoryData<string> ValidFixtures => [.. Valid.Select(fixture => fixture.Id)];

    public static TheoryData<string> ExactFixtures => [.. Valid.Where(fixture => fixture.Policy.IsExact).Select(fixture => fixture.Id)];

    public static TheoryData<string> MatrixedFixtures => [.. Valid.Where(IsMatrixed).Select(fixture => fixture.Id)];

    private static IEnumerable<GoldenFixture> Valid => GoldenCorpus.Default.GetIds(format: "avif", kind: FixtureKinds.Valid).Select(id => GoldenCorpus.Default.Get(id));

    private static bool HasFeatureKey(GoldenFixture fixture, string key) => (fixture.Entry.Features ?? []).Any(feature => feature == key || feature.StartsWith(key + "=", StringComparison.Ordinal));

    private static bool IsMatrixed(GoldenFixture fixture) => (fixture.Entry.Features ?? []).Any(feature => feature.StartsWith("avif.matrix=", StringComparison.Ordinal) && feature != "avif.matrix=0");

    [Fact]
    public void FixturesCoverTheDecoderFeatures()
    {
        var fixtures = Valid.ToList();
        var features = fixtures.SelectMany(fixture => fixture.Entry.Features ?? []).SelectMany(Expand).ToHashSet(StringComparer.Ordinal);
        foreach (var feature in new[]
        {
            "avif.majorBrand=avif", "avif.majorBrand=avis", "avif.majorBrand=mif1",
            "avif.bitDepth=8", "avif.bitDepth=10", "avif.bitDepth=12",
            "avif.subsampling=4:4:4", "avif.subsampling=4:2:2", "avif.subsampling=4:2:0", "avif.subsampling=4:0:0",
            "avif.matrix=0", "avif.matrix=1", "avif.matrix=2", "avif.matrix=4", "avif.matrix=5", "avif.matrix=6", "avif.matrix=7", "avif.matrix=8", "avif.matrix=9", "avif.range=full", "avif.range=limited",
            "avif.colr=nclx", "avif.colr=icc", "avif.colr=none", "avif.chromaSamplePosition=vertical", "avif.chromaSamplePosition=colocated",
            "avif.lossless", "avif.filmGrain", "avif.alpha", "avif.grid=2x2", "avif.grid=2x1", "avif.grid=3x1", "avif.grid=1x3", "avif.grid=3x2", "avif.gridTileTransforms", "avif.clap",
            "avif.irot=0", "avif.irot=1", "avif.irot=2", "avif.irot=3", "avif.imir=0", "avif.imir=1",
            "avif.metadata=exif", "avif.metadata=xmp",
            "avif.layout=media-first", "avif.idat", "avif.extents=3", "avif.boxes=free", "avif.boxes=unknown", "avif.boxes=large-size", "avif.boxes=to-end", "avif.trailingData",
            "avif.sequence", "avif.seq.interFrames", "avif.seq.editList=none", "avif.seq.editList=once", "avif.seq.editList=repeat", "avif.seq.editList=repeat-indefinite",
            "avif.seq.sampleSizes=stsz", "avif.seq.sampleSizes=stz2", "avif.seq.chunkOffsets=stco", "avif.seq.chunkOffsets=co64",
            "avif.seq.metadataSource=track", "avif.seq.metadataSource=file", "avif.seq.metadataAfterSamples", "avif.seq.fileMetadataNotRead", "avif.seq.samplesOutOfOrder",
            "avif.layers=2", "avif.layers=3", "avif.layers=4", "avif.layers.scaled", "avif.a1lx",
            "avif.lsel=0", "avif.lsel=1", "avif.lsel=2", "avif.lsel=3", "avif.lsel=65535", "avif.a1op=0", "avif.a1op=1", "avif.a1op=2",
        })
        {
            Assert.Contains(feature, features);
        }

        // Odd sizes (odd chroma planes), every documented pixel format, a rotation combined with a mirror and with a clean
        // aperture, matrixed content at every bit depth and in both ranges, and sequences with and without alpha
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.subsampling=4:2:0") && fixture.Expected.Width % 2 == 1 && fixture.Expected.Height % 2 == 1);
        Assert.Equal(["Gray16", "Gray8", "Rgb24", "Rgba32", "Rgba64"], fixtures.Select(fixture => fixture.Expected.PixelFormat).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray());
        Assert.Equal(["Grayscale", "GrayscaleAlpha", "Rgb", "Rgba", "YCbCr"], fixtures.Select(fixture => fixture.Expected.ColorModel!).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray());
        Assert.Contains(fixtures, fixture => fixture.Entry.Features!.Count(feature => feature.StartsWith("avif.irot=", StringComparison.Ordinal) || feature.StartsWith("avif.imir=", StringComparison.Ordinal)) == 2);
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.clap") && fixture.Expected.Orientation != 1);
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.clap") && fixture.Entry.HasFeature("avif.subsampling=4:2:0"));
        Assert.Equal([1, 2, 3, 4, 6, 7, 8], fixtures.Select(fixture => fixture.Expected.Orientation).Distinct().Order().ToArray());
        foreach (var depth in new[] { 8, 10, 12 })
        {
            Assert.Contains(fixtures, fixture => IsMatrixed(fixture) && fixture.Expected.BitsPerComponent == depth);
        }

        Assert.Contains(fixtures, fixture => IsMatrixed(fixture) && fixture.Entry.HasFeature("avif.range=limited") && fixture.Expected.BitsPerComponent == 10);
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.sequence") && fixture.Entry.HasFeature("avif.alpha"));
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.sequence") && fixture.Expected.PixelFormat == "Rgba64");
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.grid=2x1") && fixture.Entry.HasFeature("avif.alpha"));
        Assert.Contains(fixtures, fixture => fixture.Expected.Cicp is { ColorPrimaries: 9, TransferCharacteristics: 16, MatrixCoefficients: 9 }); // HDR: BT.2020, PQ

        // A grid whose image is smaller than its tiles
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.grid=2x2") && (fixture.Expected.Width, fixture.Expected.Height) == (100, 90));

        // Sequences with frames that are decoded without being shown (what avifenc writes for more than a few images)
        Assert.Contains(fixtures, fixture => HasFeatureKey(fixture, "avif.seq.hiddenFrames"));

        // Every matrix of the documented conversion in both ranges (YCgCo is only defined for the full range by the
        // encoder of the corpus), at 8 bits and deeper, and each of them on subsampled chroma
        foreach (var matrix in new[] { 1, 2, 4, 5, 6, 7, 9 })
        {
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"avif.matrix={matrix}")) && fixture.Entry.HasFeature("avif.range=full"));
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"avif.matrix={matrix}")) && fixture.Entry.HasFeature("avif.range=limited"));
        }

        foreach (var matrix in new[] { 1, 4, 5, 6, 7, 8, 9 })
        {
            var tag = string.Create(CultureInfo.InvariantCulture, $"avif.matrix={matrix}");
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature(tag) && fixture.Expected.BitsPerComponent == 8);
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature(tag) && fixture.Expected.BitsPerComponent > 8);
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature(tag) && !fixture.Entry.HasFeature("avif.subsampling=4:4:4"));
        }

        // Monochrome at every depth and in the limited range; alpha at every depth, lossy and lossless; odd 4:2:0 images
        // at every depth; one sample, one row, one column
        foreach (var depth in new[] { 8, 10, 12 })
        {
            Assert.Contains(fixtures, fixture => fixture.Expected.ColorModel == "Grayscale" && fixture.Expected.BitsPerComponent == depth);
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.alpha") && fixture.Expected.BitsPerComponent == depth && fixture.Entry.HasFeature("avif.lossless"));
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.alpha") && fixture.Expected.BitsPerComponent == depth && !fixture.Entry.HasFeature("avif.lossless"));
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.subsampling=4:2:0") && fixture.Expected.BitsPerComponent == depth && fixture.Expected.Width % 2 == 1 && fixture.Expected.Height % 2 == 1);
        }

        Assert.Contains(fixtures, fixture => fixture.Expected.ColorModel == "Grayscale" && fixture.Entry.HasFeature("avif.range=limited"));
        Assert.Contains(fixtures, fixture => (fixture.Expected.Width, fixture.Expected.Height) == (1, 1));
        Assert.Contains(fixtures, fixture => fixture.Expected.Width > 1 && fixture.Expected.Height == 1);
        Assert.Contains(fixtures, fixture => fixture.Expected.Width == 1 && fixture.Expected.Height > 1);
        Assert.Contains(fixtures, fixture => fixture.Expected.Width > 64 && fixture.Expected.Height > 64 && !HasFeatureKey(fixture, "avif.grid"));

        // Grids with alpha, of deep samples, and written by avifenc with the transformations repeated on the tiles
        Assert.Contains(fixtures, fixture => HasFeatureKey(fixture, "avif.grid") && fixture.Entry.HasFeature("avif.alpha") && fixture.Entry.HasFeature("avif.lossless"));
        Assert.Contains(fixtures, fixture => HasFeatureKey(fixture, "avif.grid") && fixture.Expected.BitsPerComponent == 10);
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.gridTileTransforms") && fixture.Entry.HasFeature("avif.clap") && fixture.Expected.Orientation != 1);

        // Film grain on every subsampling, at every depth, under an alpha plane
        foreach (var subsampling in new[] { "4:0:0", "4:2:0", "4:2:2", "4:4:4" })
        {
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.filmGrain") && fixture.Entry.HasFeature("avif.subsampling=" + subsampling));
        }

        Assert.Equal([8, 10, 12], fixtures.Where(fixture => fixture.Entry.HasFeature("avif.filmGrain")).Select(fixture => fixture.Expected.BitsPerComponent).Distinct().Order().ToArray());
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.filmGrain") && fixture.Entry.HasFeature("avif.alpha"));

        // Layered images: written by avifenc with layers of the size of the image and of growing sizes, with an alpha plane
        // that is layered too, at 8, 10 and 12 bits, monochrome and matrixed; a grid of layered tiles, tiles that select
        // their own layer and their own operating point, and a sequence of layered samples; a layer and an operating point
        // selected on matrixed content, together, and with a frame that is smaller than the last layer
        var layered = fixtures.Where(fixture => HasFeatureKey(fixture, "avif.layers")).ToList();
        Assert.Contains(layered, fixture => fixture.Entry.Provenance.Origin == "generated" && fixture.Entry.Provenance.Commands!.Any(command => command.Contains(" --progressive ", StringComparison.Ordinal)));
        Assert.Contains(layered, fixture => fixture.Entry.Provenance.Origin == "generated" && fixture.Entry.Provenance.Commands!.Any(command => command.Contains(" --layered ", StringComparison.Ordinal)) && fixture.Entry.HasFeature("avif.layers.scaled"));
        Assert.Contains(layered, fixture => fixture.Entry.HasFeature("avif.alpha"));
        Assert.Equal([8, 10, 12], layered.Select(fixture => fixture.Expected.BitsPerComponent).Distinct().Order().ToArray());
        Assert.Contains(layered, fixture => fixture.Expected.ColorModel == "Grayscale");
        Assert.Contains(layered, fixture => IsMatrixed(fixture) && fixture.Entry.HasFeature("avif.subsampling=4:2:0"));
        Assert.Contains(layered, fixture => IsMatrixed(fixture) && fixture.Entry.HasFeature("avif.subsampling=4:2:2"));
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.grid") && !HasFeatureKey(fixture, "avif.lsel") && !HasFeatureKey(fixture, "avif.a1op"));
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.grid") && fixture.Entry.HasFeature("avif.lsel=0,1"));
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.grid") && fixture.Entry.HasFeature("avif.a1op=1,2"));
        Assert.Contains(layered, fixture => fixture.Entry.HasFeature("avif.sequence") && fixture.Expected.FrameCount > 1);
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.lsel") && IsMatrixed(fixture));
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.lsel") && HasFeatureKey(fixture, "avif.a1op"));
        Assert.Contains(layered, fixture => fixture.Entry.HasFeature("avif.lsel=0") && fixture.Entry.HasFeature("avif.layers.scaled"));
        Assert.Contains(layered, fixture => fixture.Entry.HasFeature("avif.a1op=1") && fixture.Entry.HasFeature("avif.layers.scaled"));

        // Lower layers that are decoded on the way, and a selected layer that has none below it
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.lsel") && HasFeatureKey(fixture, "avif.layers.hiddenPixels"));
        Assert.Contains(layered, fixture => HasFeatureKey(fixture, "avif.lsel") && !HasFeatureKey(fixture, "avif.layers.hiddenPixels"));
        Assert.All(layered.Where(fixture => !HasFeatureKey(fixture, "avif.lsel") && !HasFeatureKey(fixture, "avif.a1op")), fixture => Assert.True(HasFeatureKey(fixture, "avif.layers.hiddenPixels"), $"{fixture.Id}: the lower layers of a layered image are decoded."));

        // No colr box: identity and matrixed bitstreams, the bitstream after and before the meta box, no color description
        // at all; a profile without nclx description
        foreach (var mediaFirst in new[] { false, true })
        {
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.colr=none") && fixture.Expected.ColorModel == "Rgb" && fixture.Entry.HasFeature("avif.layout=media-first") == mediaFirst);
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.colr=none") && fixture.Expected.ColorModel == "YCbCr" && fixture.Entry.HasFeature("avif.layout=media-first") == mediaFirst && !fixture.Entry.HasFeature("avif.sequence"));
        }

        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("avif.colr=none") && fixture.Expected.Cicp is null && !fixture.Entry.HasFeature("avif.sequence"));
        Assert.Contains(fixtures, fixture => fixture.Entry.Features!.Contains("avif.colr=icc", StringComparer.Ordinal));

        // Sequences: 8 images and more, every subsampling, 10 and 12 bits, lossy alpha, each metadata source with the item
        // data in the mdat box, in an idat box and after the samples, an ICC profile, a second muxer and a second encoder
        var sequences = fixtures.Where(fixture => fixture.Entry.HasFeature("avif.sequence")).ToList();
        Assert.Contains(sequences, fixture => fixture.Expected.FrameCount >= 12);
        foreach (var subsampling in new[] { "4:0:0", "4:2:0", "4:2:2", "4:4:4" })
        {
            Assert.Contains(sequences, fixture => fixture.Expected.FrameCount >= 8 && fixture.Entry.HasFeature("avif.subsampling=" + subsampling));
        }

        Assert.Contains(sequences, fixture => fixture.Expected.FrameCount >= 8 && fixture.Expected.BitsPerComponent == 10);
        Assert.Contains(sequences, fixture => fixture.Expected.FrameCount >= 8 && fixture.Expected.BitsPerComponent == 12);
        Assert.Contains(sequences, fixture => fixture.Expected.FrameCount >= 8 && fixture.Entry.HasFeature("avif.alpha") && !fixture.Entry.HasFeature("avif.lossless"));
        Assert.Contains(sequences, fixture => fixture.Entry.HasFeature("avif.alpha") && fixture.Expected.BitsPerComponent == 10);
        Assert.Contains(sequences, fixture => fixture.Expected.IccProfile != "none");
        foreach (var source in new[] { "track", "file" })
        {
            var tag = "avif.seq.metadataSource=" + source;
            Assert.Contains(sequences, fixture => fixture.Entry.HasFeature(tag) && fixture.Expected.Profiles.Exif is not null && fixture.Expected.Profiles.Xmp is not null && !fixture.Entry.HasFeature("avif.idat") && !fixture.Entry.HasFeature("avif.seq.metadataAfterSamples"));
            Assert.Contains(sequences, fixture => fixture.Entry.HasFeature(tag) && fixture.Entry.HasFeature("avif.idat"));
            Assert.Contains(sequences, fixture => fixture.Entry.HasFeature(tag) && fixture.Entry.HasFeature("avif.seq.metadataAfterSamples"));
        }

        Assert.Contains(sequences, fixture => fixture.Entry.HasFeature("avif.seq.fileMetadataNotRead") && fixture.Entry.HasFeature("avif.seq.metadataSource=track"));
        Assert.Contains(sequences, fixture => fixture.Entry.HasFeature("avif.seq.fileMetadataNotRead") && fixture.Expected.Profiles.Exif is null && fixture.Expected.Profiles.Xmp is null);
        Assert.HasCountGreaterThanOrEqual(2, sequences.Where(fixture => fixture.Entry.Provenance.Tools!.Any(tool => tool.Contains("avif muxer", StringComparison.Ordinal))).ToList());
        Assert.Contains(sequences, fixture => fixture.Entry.Provenance.Tools!.Any(tool => tool.Contains("SVT-AV1", StringComparison.Ordinal)));

        static IEnumerable<string> Expand(string feature)
        {
            var separator = feature.IndexOf('=', StringComparison.Ordinal);
            return separator < 0 ? [feature] : feature[(separator + 1)..].Split(',').Select(value => feature[..(separator + 1)] + value);
        }
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void DecodedImageHasTheStructureOfTheFile(string id)
    {
        // The independent reader gives the structure; the manifest must say the same, and so must the library
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var file = ReferenceAvif.Parse(data);
        var expected = fixture.Expected;
        using var image = Image.Load(data);
        var info = Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan });

        ReferenceAvif.Av1Configuration configuration;
        ReferenceAvif.ColorDescription? nclx;
        ReadOnlyMemory<byte>? icc;
        bool hasAlpha;
        int alphaBitDepth;
        (int Width, int Height) size;
        var orientation = 1;
        if (file.IsSequence)
        {
            var track = file.ColorTrack;
            Assert.NotNull(track);
            configuration = track.Configuration!;
            nclx = track.Nclx;
            icc = track.IccProfile;
            hasAlpha = file.AlphaTrack is not null;
            alphaBitDepth = file.AlphaTrack?.Configuration?.BitDepth ?? 0;
            size = (track.Width, track.Height);

            // The clean aperture of the sample entry is the part of the samples that is shown, and the matrix of the track
            // header the orientation of the images
            if (track.CleanAperture is { } trackAperture)
            {
                var rectangle = trackAperture.GetRectangle(track.Width, track.Height);
                Assert.NotNull(rectangle);
                size = (rectangle.Value.Width, rectangle.Value.Height);
                Assert.True(fixture.Entry.HasFeature("avif.seq.clap"));
            }

            orientation = track.Orientation;
            Assert.Equal(orientation != 1, fixture.Entry.Features?.Any(feature => feature.StartsWith("avif.seq.matrix=", StringComparison.Ordinal)) ?? false);

            // One image per sample, the duration of each sample over the time scale of the media, the plays of the edit list
            Assert.Equal(track.Samples.Count, expected.FrameCount);
            Assert.Equal(track.Samples.Count, image.Frames.Count);
            Assert.Equal(track.Samples.Count, info.FrameCount);
            for (var i = 0; i < track.Samples.Count; i++)
            {
                var duration = new FrameDuration(track.Samples[i].Duration, track.Timescale);
                Assert.Equal(duration, image.Frames[i].Metadata.Duration);
                Assert.Equal(RationalDuration.Create(duration.Numerator, duration.Denominator), fixture.GetDuration(i));
            }

            Assert.Equal(track.Samples.Count > 1, image.Animation is not null);
            if (track.Samples.Count > 1)
            {
                Assert.Equal(track.TotalPlays, expected.Animation!.TotalPlays);
                Assert.Equal(track.TotalPlays, image.Animation!.TotalPlays);
                Assert.Equal(track.TotalPlays, info.Animation!.TotalPlays);
            }

            if (file.AlphaTrack is { } alphaTrack)
            {
                Assert.Equal(track.Samples.Count, alphaTrack.Samples.Count);
                Assert.Equal((track.Width, track.Height), (alphaTrack.Width, alphaTrack.Height));
            }

            // The Exif and XMP items of a sequence: those of the meta box of its track, or else of the meta box of the
            // file when it precedes the moov box. A header identification does not read them
            var (exif, xmp) = file.FindSequenceMetadata();
            var expectedExif = exif is null ? null : Convert.ToHexString(file.ReadExifPayload(exif));
            var expectedXmp = xmp is null ? null : Convert.ToHexString(file.ReadItemData(xmp));
            Assert.Equal(expectedExif, image.Metadata.ExifProfile is { } exifProfile ? Convert.ToHexString(exifProfile.Data.Span) : null);
            Assert.Equal(expectedXmp, image.Metadata.XmpProfile is { } xmpProfile ? Convert.ToHexString(xmpProfile.Data.Span) : null);
            Assert.Equal(expectedExif, info.Metadata.ExifProfile is { } scannedExif ? Convert.ToHexString(scannedExif.Data.Span) : null);
            Assert.Equal(expectedXmp, info.Metadata.XmpProfile is { } scannedXmp ? Convert.ToHexString(scannedXmp.Data.Span) : null);
            Assert.Equal(exif is not null, expected.Profiles.Exif is not null);
            Assert.Equal(xmp is not null, expected.Profiles.Xmp is not null);
            var header = Image.Identify(data);
            Assert.Null(header.Metadata.ExifProfile);
            Assert.Null(header.Metadata.XmpProfile);
            Assert.Equal(track.Samples.Count, header.FrameCount);
        }
        else
        {
            var primary = file.PrimaryItem;
            Assert.NotNull(primary);
            var coded = primary;
            if (primary.Type == "grid")
            {
                var (rows, columns, width, height) = file.ReadGridDescriptor(primary);
                var tiles = file.GetGridTiles(primary);
                Assert.Equal(rows * columns, tiles.Count);
                Assert.Equal(primary.Size, (width, height));
                Assert.True(fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"avif.grid={columns}x{rows}")));
                coded = tiles[0];
            }

            configuration = coded.Configuration!;
            nclx = primary.Nclx;
            icc = primary.IccProfile;
            hasAlpha = file.AlphaItem is not null;
            alphaBitDepth = file.AlphaItem is { } alpha ? (alpha.Type == "grid" ? file.GetGridTiles(alpha)[0] : alpha).Configuration!.BitDepth : 0;
            var ispe = primary.Size!.Value;
            size = ((int)ispe.Width, (int)ispe.Height);
            if (primary.CleanAperture is { } aperture)
            {
                var rectangle = aperture.GetRectangle(size.Width, size.Height);
                Assert.NotNull(rectangle);
                size = (rectangle.Value.Width, rectangle.Value.Height);
            }

            orientation = primary.Orientation;
            Assert.Single(image.Frames);
            Assert.Null(image.Animation);
            Assert.Equal(FrameDuration.Zero, image.Frames[0].Metadata.Duration);

            var descriptions = file.FindDescriptions(primary.Id);
            var exif = descriptions.FirstOrDefault(item => item.Type == "Exif");
            var xmp = descriptions.FirstOrDefault(item => item.ContentType == "application/rdf+xml");
            Assert.Equal(exif is null ? null : Convert.ToHexString(file.ReadExifPayload(exif)), image.Metadata.ExifProfile is { } stillExif ? Convert.ToHexString(stillExif.Data.Span) : null);
            Assert.Equal(xmp is null ? null : Convert.ToHexString(file.ReadItemData(xmp)), image.Metadata.XmpProfile is { } stillXmp ? Convert.ToHexString(stillXmp.Data.Span) : null);
        }

        // Size (the clean aperture is applied, the orientation is not), orientation, pixel format, bit depth
        Assert.Equal(size, (expected.Width, expected.Height));
        Assert.Equal(size, (image.Width, image.Height));
        Assert.Equal(size, (info.Width, info.Height));
        Assert.Equal(orientation, expected.Orientation);
        Assert.Equal((ExifOrientation)orientation, image.Metadata.Orientation);
        Assert.Equal((ExifOrientation)orientation, info.Metadata.Orientation);
        var deep = Math.Max(configuration.BitDepth, alphaBitDepth) > 8;
        var pixelFormat = configuration.IsMonochrome && !hasAlpha
            ? (deep ? PixelFormat.Gray16 : PixelFormat.Gray8)
            : deep ? PixelFormat.Rgba64 : hasAlpha ? PixelFormat.Rgba32 : PixelFormat.Rgb24;
        Assert.Equal(pixelFormat.ToString(), expected.PixelFormat);
        Assert.Equal(pixelFormat, image.PixelFormat);
        Assert.Equal(pixelFormat, info.PixelFormat);
        Assert.Equal(configuration.BitDepth, expected.BitsPerComponent);
        Assert.Equal(configuration.BitDepth, info.BitsPerComponent);
        Assert.Equal(hasAlpha, info.MayHaveTransparency);
        Assert.Equal(hasAlpha, fixture.Entry.HasFeature("avif.alpha"));
        Assert.Equal(ImageFormat.Avif, image.Metadata.SourceFormat);

        // A colr box of type nclx is the color description; otherwise the manifest holds the one of the bitstream
        if (nclx is not null)
        {
            Assert.Equal(new CicpColorDescription((byte)nclx.ColorPrimaries, (byte)nclx.TransferCharacteristics, (byte)nclx.MatrixCoefficients, nclx.FullRange), image.Metadata.Cicp);
        }

        var expectedCicp = expected.Cicp is { } cicp ? new CicpColorDescription((byte)cicp.ColorPrimaries, (byte)cicp.TransferCharacteristics, (byte)cicp.MatrixCoefficients, cicp.FullRange) : null;
        Assert.Equal(expectedCicp, image.Metadata.Cicp);
        Assert.Equal(expectedCicp, info.Metadata.Cicp);
        Assert.Equal(icc is null ? null : Convert.ToHexString(icc.Value.Span), image.Metadata.IccProfile is { } profile ? Convert.ToHexString(profile.Data.Span) : null);

        // Color profiles and color descriptions are labels: neither changes the transfer function label
        Assert.Equal(ColorTransferFunction.Srgb, image.Metadata.TransferFunction);
    }

