    [Theory]
    [MemberData(nameof(MatrixedFixtures))]
    public void ToleranceIsTheMeasuredDisagreementWithTheReference(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        using var image = Image.Load(fixture.ReadInput());
        var snapshot = ImageSnapshots.Capture(image);
        Assert.Equal(fixture.Expected.FrameCount, snapshot.Frames.Count);
        var max = 0;
        var sum = 0.0;
        var location = "(none)";
        for (var i = 0; i < snapshot.Frames.Count; i++)
        {
            var actual = snapshot.Frames[i].Pixels;
            var (frameMax, frameMean, frameLocation) = Measure(fixture.GetFrame(i, actual.Layout), actual);
            sum += frameMean;
            if (frameMax > max)
            {
                max = frameMax;
                location = string.Create(CultureInfo.InvariantCulture, $"frame {i} {frameLocation}");
            }
        }

        // Errors on the 8-bit scale: a unit of a 16-bit sample is 1/257
        var scale = snapshot.Frames[0].Pixels.Layout.ScaleFrom8Bit;
        var mean = Math.Round(sum / snapshot.Frames.Count / scale, 4, MidpointRounding.AwayFromZero);
        var units = (max + scale - 1) / scale;
        TestContext.Current.TestOutputHelper?.WriteLine(string.Create(CultureInfo.InvariantCulture, $"[\"{id}\"] = ({units}, {mean:0.0###}), // max {max} at {location}"));

        // The AV1 planes are exact; only the rounding of the matrix coefficients differs from the exact conversion
        Assert.True(units <= 1, string.Create(CultureInfo.InvariantCulture, $"'{id}' differs from the exact conversion by {max} at {location}: more than one unit."));

        var policy = fixture.Policy;
        Assert.False(policy.IsExact, $"'{id}' is matrixed: its policy is a tolerance of one unit (every independent cross-check agrees exactly with the reference?).");
        var checks = fixture.Entry.Reference?.CrossChecks?.Where(check => check.ExcludedFromTolerance != true && check.MaxAbsoluteError is not null).ToList() ?? [];
        Assert.NotEmpty(checks);
        var (justifiedMax, justifiedMean) = ComparisonPolicy.GetMaximumJustifiedTolerance(checks.Max(check => check.MaxAbsoluteError!.Value), checks.Max(check => check.MeanAbsoluteError!.Value));
        var expectedMax = Math.Min(justifiedMax, 1);
        var expectedMean = Math.Min(justifiedMean, Math.Ceiling(Math.Round((mean + 0.01) * 100, 6, MidpointRounding.AwayFromZero)) / 100);
        Assert.True(policy.MaxAbsoluteError == expectedMax && Math.Abs(policy.MaxMeanAbsoluteError - expectedMean) < 1e-9,
            string.Create(CultureInfo.InvariantCulture, $"The policy of '{id}' (max {policy.MaxAbsoluteError}, mean {policy.MaxMeanAbsoluteError}) is not the one derived from the measured disagreement (max {units}, mean {mean}: max {expectedMax}, mean {expectedMean}). Update LibraryAvifMeasurements in tools/Meziantou.Framework.Imaging.CorpusGenerator/AvifCorpus.Container.cs after reviewing the change."));
    }

    public static TheoryData<string> FixturesWithoutColorDescriptionBox => [.. Valid.Where(fixture => !(fixture.Entry.Features ?? []).Any(feature => feature.StartsWith("avif.colr=", StringComparison.Ordinal) && feature.Split('=')[1].Split(',').Contains("nclx", StringComparer.Ordinal))).Select(fixture => fixture.Id)];

    [Theory]
    [MemberData(nameof(FixturesWithoutColorDescriptionBox))]
    public void HeaderIdentificationReadsTheSequenceHeaderOfAFileWithoutColorDescriptionBox(string id)
    {
        // Without colr box of type nclx the bitstream describes the colors. A header identification reads on to its
        // sequence header, and reports the color model and the color description a full scan and a load report; when the
        // bitstream precedes the box that describes the image, it has gone by: the color model is unknown, never guessed
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var file = ReferenceAvif.Parse(data);
        Assert.Null(file.IsSequence ? file.ColorTrack!.Nclx : file.PrimaryItem!.Nclx);
        var expected = fixture.Expected;
        var expectedCicp = expected.Cicp is { } cicp ? new CicpColorDescription((byte)cicp.ColorPrimaries, (byte)cicp.TransferCharacteristics, (byte)cicp.MatrixCoefficients, cicp.FullRange) : null;
        var full = Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan });
        Assert.Equal(Enum.Parse<ImageColorModel>(expected.ColorModel!), full.ColorModel);
        Assert.Equal(expectedCicp, full.Metadata.Cicp);

        var stream = new MemoryStream(data);
        var header = Image.Identify(stream);
        Assert.Equal(ImageIdentifyMode.Header, header.IdentifyMode);
        Assert.Equal((expected.Width, expected.Height), (header.Width, header.Height));
        Assert.Equal(Enum.Parse<PixelFormat>(expected.PixelFormat), header.PixelFormat);
        if (FixtureTraits.HeaderCannotTellTheColorModel(fixture))
        {
            Assert.True(fixture.Entry.HasFeature("avif.layout=media-first"));
            Assert.Equal(ImageColorModel.Unknown, header.ColorModel);
            Assert.Null(header.Metadata.Cicp);
        }
        else
        {
            Assert.Equal(full.ColorModel, header.ColorModel);
            Assert.Equal(expectedCicp, header.Metadata.Cicp);
        }
    }

