    [Fact]
    public void ColorBoxDescribesTheColorsBeforeTheBitstream()
    {
        // Three containers around the same AV1 payload, whose sequence header says BT.709 limited range
        var encoded = GoldenCorpus.Default.Get("avif/lossy-422-bt709-limited");
        var overridden = GoldenCorpus.Default.Get("avif/nclx-overrides-bitstream");
        var bare = GoldenCorpus.Default.Get("avif/no-colr-bitstream-bt709");
        var payload = ReadPrimaryPayload(encoded);
        Assert.Equal(payload, ReadPrimaryPayload(overridden));
        Assert.Equal(payload, ReadPrimaryPayload(bare));

        using var first = Image.Load(encoded.ReadInput());
        using var second = Image.Load(overridden.ReadInput());
        using var third = Image.Load(bare.ReadInput());
        Assert.Equal(new CicpColorDescription(1, 13, 1, fullRange: false), first.Metadata.Cicp);
        Assert.Equal(new CicpColorDescription(1, 13, 6, fullRange: true), second.Metadata.Cicp);
        Assert.Equal(new CicpColorDescription(1, 13, 1, fullRange: false), third.Metadata.Cicp);

        // Same description, same pixels (the references are one file); another description, other pixels
        Assert.Equal(encoded.Expected.Frames[0].Buffers[0].Sha256, bare.Expected.Frames[0].Buffers[0].Sha256);
        Assert.NotEqual(encoded.Expected.Frames[0].Buffers[0].Sha256, overridden.Expected.Frames[0].Buffers[0].Sha256);
        Assert.Equal(ImageSnapshots.Capture(first).Frames[0].Pixels.Span, ImageSnapshots.Capture(third).Frames[0].Pixels.Span);
        Assert.NotEqual(ImageSnapshots.Capture(first).Frames[0].Pixels.ToArray(), ImageSnapshots.Capture(second).Frames[0].Pixels.ToArray());

        static string ReadPrimaryPayload(GoldenFixture fixture)
        {
            var file = ReferenceAvif.Parse(fixture.ReadInput());
            return Convert.ToHexString(file.ReadItemData(file.PrimaryItem!));
        }
    }

