    [Fact]
    public void SequenceMetadataComeFromTheTrackOrElseFromAFileMetaBoxThatPrecedesTheMovie()
    {
        // The same three images and the same Exif and XMP payloads in every place a sequence takes them from; where the
        // meta box of the file is not read, the sequence has none, or only the items of its track
        var plain = GoldenCorpus.Default.Get("avif/sequence-lossless-infinite");
        var withBoth = new[]
        {
            "avif/sequence-file-meta-exif-xmp", "avif/sequence-file-meta-idat", "avif/sequence-file-meta-after-samples",
            "avif/sequence-track-meta-exif-xmp", "avif/sequence-track-meta-idat", "avif/sequence-track-meta-after-samples",
        }.Select(id => GoldenCorpus.Default.Get(id)).ToList();
        var reference = withBoth[0].Expected.Profiles;
        Assert.NotNull(reference.Exif);
        Assert.NotNull(reference.Xmp);
        foreach (var fixture in withBoth)
        {
            Assert.Equal((reference.Exif.Sha256, reference.Xmp.Sha256), (fixture.Expected.Profiles.Exif!.Sha256, fixture.Expected.Profiles.Xmp!.Sha256));
            Assert.Equal(plain.Expected.Frames.Select(frame => (frame.Duration, frame.Buffers[0].Sha256)), fixture.Expected.Frames.Select(frame => (frame.Duration, frame.Buffers[0].Sha256)));
            using var image = Image.Load(fixture.ReadInput());
            Assert.True(reference.Exif.Matches(image.Metadata.ExifProfile!.Data.Span) && reference.Xmp.Matches(image.Metadata.XmpProfile!.Data.Span), fixture.Id);

            // The Exif payload says "rotate 90 degrees": the images of a sequence are returned as stored
            Assert.Equal(ExifOrientation.RightTop, ExifTiff.ReadOrientation(image.Metadata.ExifProfile!.Data.Span));
            Assert.Equal(ExifOrientation.TopLeft, image.Metadata.Orientation);
        }

        // The track has a meta box with an XMP item only; the Exif item and the other XMP item of the file are not read
        var trackWins = GoldenCorpus.Default.Get("avif/sequence-track-meta-wins");
        var file = ReferenceAvif.Parse(trackWins.ReadInput());
        Assert.Contains(file.Items, item => item.Type == "Exif");
        var fileXmp = file.Items.Single(item => item.ContentType == "application/rdf+xml");
        var trackXmp = file.ColorTrack!.MetaItems.Single(item => item.ContentType == "application/rdf+xml");
        Assert.NotEqual(Convert.ToHexString(file.ReadItemData(fileXmp)), Convert.ToHexString(file.ReadItemData(trackXmp)));
        using (var image = Image.Load(trackWins.ReadInput()))
        {
            Assert.Null(image.Metadata.ExifProfile);
            Assert.Equal(Convert.ToHexString(file.ReadItemData(trackXmp)), Convert.ToHexString(image.Metadata.XmpProfile!.Data.Span));
            Assert.Equal(reference.Xmp.Sha256, trackWins.Expected.Profiles.Xmp!.Sha256);
        }

        // The meta box of the file follows the moov box
        var late = GoldenCorpus.Default.Get("avif/sequence-file-meta-after-moov");
        var lateFile = ReferenceAvif.Parse(late.ReadInput());
        Assert.Equal(["ftyp", "moov", "meta", "mdat"], lateFile.TopLevelBoxes.Select(box => box.Type).ToArray());
        Assert.Contains(lateFile.Items, item => item.Type == "Exif");
        Assert.False(lateFile.ColorTrack!.HasMeta);
        using (var image = Image.Load(late.ReadInput()))
        {
            Assert.Null(image.Metadata.ExifProfile);
            Assert.Null(image.Metadata.XmpProfile);
        }
    }

