    [Fact]
    public void FramesThatAreNotShownCountTowardTheTotalPixels()
    {
        // The samples of the fixture are the temporal units of an AV1 vector that has hidden frames (its provenance records
        // how many, as read from the headers by trace_headers): the limit is reached one pixel below what is decoded,
        // although it is far above what is displayed
        var fixture = GoldenCorpus.Default.Get("limit/avif/sequence-hidden-frames-total-pixels");
        var parameters = fixture.Entry.Provenance.Parameters!.Value;
        var pixels = (long)parameters.GetProperty("width").GetInt32() * parameters.GetProperty("height").GetInt32();
        var shown = parameters.GetProperty("shownFrames").GetInt32();
        var hidden = parameters.GetProperty("hiddenFrames").GetInt32();
        Assert.True(hidden > 0);
        var required = (shown + hidden) * pixels;
        Assert.Equal(required - 1, fixture.Entry.DecodeOptions!.Limits!["MaxTotalPixels"]);
        var data = fixture.ReadInput();
        Assert.Equal(shown, ReferenceAvif.Parse(data).ColorTrack!.Samples.Count);

        using (var image = Image.Load(data, Options(required)))
        {
            Assert.Equal(shown, image.Frames.Count);
        }

        var exception = Assert.Throws<ImageResourceLimitException>(() => Image.Load(data, Options(required - 1)).Dispose());
        Assert.Equal(ImageResourceLimitKind.TotalPixels, exception.Kind);
        Assert.Equal(required - 1, exception.Limit);
        Assert.True(required - 1 >= shown * pixels, "The limit is enough for the displayed images.");

        // Identification decodes nothing: the hidden frames are only charged when they are decoded
        Assert.Equal(shown, Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan, Configuration = Options(1).Configuration }).FrameCount);

        static ImageDecodeOptions Options(long maxTotalPixels) => new() { Configuration = new ImageConfiguration { Limits = new ImageResourceLimits { MaxTotalPixels = maxTotalPixels } } };
    }

    [Fact]
    public void LowerLayersCountTowardTheTotalPixels()
    {
        // The fixture reuses a layered image whose lower layers are smaller than the image: the limit is reached one pixel
        // below what is decoded (the image and its lower layers, each with its own size), although it is above what is
        // displayed. The sizes of the layers come from the generator (the frame headers as trace_headers reads them)
        var fixture = GoldenCorpus.Default.Get("limit/avif/layered-lower-layers-total-pixels");
        var parameters = fixture.Entry.Provenance.Parameters!.Value;
        var source = GoldenCorpus.Default.Get(parameters.GetProperty("fixture").GetString()!);
        var displayed = parameters.GetProperty("displayedPixels").GetInt64();
        var lowerLayers = parameters.GetProperty("lowerLayerPixels").GetInt64();
        Assert.Equal((long)source.Expected.Width * source.Expected.Height, displayed);
        Assert.Equal(FixtureTraits.GetHiddenPixelCount(source), lowerLayers);
        Assert.True(lowerLayers > 0 && lowerLayers % displayed != 0, "The lower layers do not have the size of the image.");
        var required = displayed + lowerLayers;
        Assert.Equal(required - 1, fixture.Entry.DecodeOptions!.Limits!["MaxTotalPixels"]);
        var data = fixture.ReadInput();
        Assert.Equal(Convert.ToHexString(source.ReadInput()), Convert.ToHexString(data));

        using (var image = Image.Load(data, Options(required)))
        {
            Assert.Single(image.Frames);
        }

        var exception = Assert.Throws<ImageResourceLimitException>(() => Image.Load(data, Options(required - 1)).Dispose());
        Assert.Equal(ImageResourceLimitKind.TotalPixels, exception.Kind);
        Assert.Equal(required - 1, exception.Limit);
        Assert.True(required - 1 >= displayed, "The limit is enough for the displayed image.");

        // Identification decodes nothing: the lower layers are only charged when they are decoded
        Assert.Equal(1, Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan, Configuration = Options(1).Configuration }).FrameCount);

        // The layers above a selected layer are not decoded and count for nothing: with the second layer of the three
        // selected (4x4, 8x8 and 16x16), the image is 8x8 and the first layer is the only one below it
        var file = ReferenceAvif.Parse(data);
        Assert.Equal([0, 1, 2], ReferenceObuStream.GetSpatialLayers(file.ReadItemData(file.PrimaryItem!)).ToArray());
        var builder = AvifFileBuilder.From(data);
        var item = builder.GetItem(file.PrimaryItem!.Id);
        item.Associations.Add((builder.AddProperty(AvifFileBuilder.LayerSelector(1)), true));
        var size = Enumerable.Range(0, item.Associations.Count).Single(index => Encoding.Latin1.GetString(builder.Properties[item.Associations[index].PropertyIndex - 1].AsSpan(4, 4)) == "ispe");
        item.Associations[size] = (builder.AddProperty(AvifFileBuilder.ImageSize((uint)source.Expected.Width / 2, (uint)source.Expected.Height / 2)), item.Associations[size].IsEssential);
        var second = builder.Build();
        var secondRequired = (displayed / 4) + (displayed / 16);
        Assert.True(secondRequired < displayed);
        using (var image = Image.Load(second, Options(secondRequired)))
        {
            Assert.Equal((source.Expected.Width / 2, source.Expected.Height / 2), (image.Width, image.Height));
        }

        exception = Assert.Throws<ImageResourceLimitException>(() => Image.Load(second, Options(secondRequired - 1)).Dispose());
        Assert.Equal(ImageResourceLimitKind.TotalPixels, exception.Kind);
        Assert.Equal(secondRequired, exception.Requested);

        static ImageDecodeOptions Options(long maxTotalPixels) => new() { Configuration = new ImageConfiguration { Limits = new ImageResourceLimits { MaxTotalPixels = maxTotalPixels } } };
    }

    public static TheoryData<string> LayeredFixtures => [.. Valid.Where(fixture => HasFeatureKey(fixture, "avif.layers")).Select(fixture => fixture.Id)];

    [Theory]
    [MemberData(nameof(LayeredFixtures))]
    public void LayeredFixturesHoldAndSelectWhatTheirFeaturesSay(string id)
    {
        // The independent readers find in the bytes what the manifest records: the spatial layers of the bitstreams, the
        // properties that select an operating point or a layer, and a selection that the bitstream has
        var fixture = GoldenCorpus.Default.Get(id);
        var file = ReferenceAvif.Parse(fixture.ReadInput());
        var layerCounts = new List<int>();
        var selectors = new SortedSet<int>();
        var operatingPoints = new SortedSet<int>();
        var hasLayerSizes = false;
        if (file.IsSequence)
        {
            // A track has no property that selects a layer: every sample gives its highest one
            layerCounts.AddRange(file.ColorTrack!.Samples.Select(sample => ReferenceObuStream.GetSpatialLayers(file.ReadSample(sample)).Count));
            Assert.All(layerCounts, count => Assert.True(count > 1, $"{id}: every sample is a layered temporal unit."));
        }
        else
        {
            var primary = file.PrimaryItem!;
            var images = new[] { primary, file.AlphaItem }.OfType<ReferenceAvif.Item>().ToList();

            // A derived image selects nothing: its tiles do
            Assert.All(images.Where(image => image.Type == "grid"), grid => Assert.True(grid.LayerSelector is null && grid.OperatingPoint is null, $"{id}: a grid item selects a layer or an operating point."));
            foreach (var coded in images.SelectMany(image => image.Type == "grid" ? file.GetGridTiles(image) : [image]))
            {
                var payload = file.ReadItemData(coded);
                var layers = ReferenceObuStream.GetSpatialLayers(payload);
                var idc = ReferenceObuStream.ReadOperatingPoints(payload);
                layerCounts.Add(layers.Count);
                Assert.Equal([.. Enumerable.Range(0, layers.Count)], layers.ToArray());

                // As avifenc writes its streams: one operating point per number of layers, from every layer to the first one
                Assert.Equal([.. Enumerable.Range(0, layers.Count).Select(index => (((1 << (layers.Count - index)) - 1) << 8) | 1)], idc.ToArray());
                hasLayerSizes |= coded.LayerSizes is not null;
                var operatingPoint = coded.OperatingPoint ?? 0;
                Assert.True(operatingPoint < idc.Count, $"{id}: the item selects an operating point that the sequence header has.");
                if (coded.OperatingPoint is { } index)
                    operatingPoints.Add(index);

                if (coded.LayerSelector is { } selector)
                {
                    selectors.Add(selector);
                    Assert.True(selector == 0xFFFF || ((idc[operatingPoint] >> (8 + selector)) & 1) == 1, $"{id}: the item selects a layer that its operating point has.");
                }

                // The sizes of the a1lx property are those of the frames of the first layers, which the library ignores
                if (coded.LayerSizes is { } sizes)
                {
                    var frames = ReferenceObuStream.ReadUnits(payload).Where(unit => unit.Type == ReferenceObuStream.Frame).ToList();
                    for (var layer = 0; layer < Math.Min(3, frames.Count - 1); layer++)
                    {
                        var first = layer == 0 ? 0 : frames[layer].Offset;
                        Assert.Equal(frames[layer + 1].Offset - first, sizes[layer]);
                    }
                }
            }
        }

        Assert.True(fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"avif.layers={layerCounts.Max()}")), $"{id}: the manifest records the number of layers.");
        Assert.Equal(hasLayerSizes, fixture.Entry.HasFeature("avif.a1lx"));
        Assert.Equal(selectors.Count == 0 ? null : "avif.lsel=" + string.Join(',', selectors), fixture.Entry.Features!.SingleOrDefault(feature => feature.StartsWith("avif.lsel=", StringComparison.Ordinal)));
        Assert.Equal(operatingPoints.Count == 0 ? null : "avif.a1op=" + string.Join(',', operatingPoints), fixture.Entry.Features!.SingleOrDefault(feature => feature.StartsWith("avif.a1op=", StringComparison.Ordinal)));
    }

    [Fact]
    public void SelectedLayersAreTheLayersOfTheirSource()
    {
        // The fixtures that select a layer or an operating point of avif/layered-3-quality-rgb present one of its three
        // layers. Their references are derived independently (the units of the other layers are removed, then both
        // decoders decode what is left): the selections that name the same layer must have the same pixels, the three
        // layers must differ, and avifdec, which reads the properties itself, must agree exactly with each of them
        string[][] groups =
        [
            ["avif/layered-3-quality-rgb", "avif/layered-lsel-none", "avif/layered-lsel-2", "avif/layered-a1op-0"],
            ["avif/layered-lsel-1", "avif/layered-a1op-1"],
            ["avif/layered-lsel-0", "avif/layered-a1op-2", "avif/layered-a1op-1-lsel-0"],
        ];
        var layers = new List<string>();
        foreach (var group in groups)
        {
            var pixels = group.Select(id => Convert.ToHexString(GoldenCorpus.Default.Get(id).GetFrame(0, RawPixelLayout.Rgba8).Span)).Distinct(StringComparer.Ordinal).ToList();
            Assert.Single(pixels);
            layers.Add(pixels[0]);
            foreach (var id in group)
            {
                var checks = GoldenCorpus.Default.Get(id).Entry.Reference!.CrossChecks!.Where(check => check.Decoder.Contains("avifdec", StringComparison.Ordinal)).ToList();
                Assert.NotEmpty(checks);
                Assert.All(checks, check => Assert.Equal("exact", check.Result, message: $"{id}: {check.Decoder}"));
            }
        }

        Assert.HasCount(3, layers.Distinct(StringComparer.Ordinal));

        // The other pairs: the last of four layers, and the smaller first layer selected either way
        foreach (var (first, second) in new[] { ("avif/layered-4-quality-gray12", "avif/layered-lsel-3"), ("avif/layered-lsel-0-smaller", "avif/layered-a1op-1-smaller") })
        {
            var (a, b) = (GoldenCorpus.Default.Get(first), GoldenCorpus.Default.Get(second));
            Assert.Equal(Convert.ToHexString(a.GetFrame(0, a.CanonicalLayout).Span), Convert.ToHexString(b.GetFrame(0, b.CanonicalLayout).Span));
        }

        // A smaller layer is the image at its own size, not the last layer scaled down
        var smaller = GoldenCorpus.Default.Get("avif/layered-lsel-0-smaller");
        var whole = GoldenCorpus.Default.Get("avif/layered-progressive-444-10bit");
        Assert.Equal((whole.Expected.Width / 2, whole.Expected.Height / 2), (smaller.Expected.Width, smaller.Expected.Height));
        Assert.Equal(ReferenceAvif.Parse(smaller.ReadInput()).PrimaryItem!.Size, ((long)smaller.Expected.Width, (long)smaller.Expected.Height));
    }

    [Fact]
    public void ErrorFixturesAreWhatTheirNotesSay()
    {
        // The independent reader confirms the structural facts that the error fixtures are built on
        Assert.True(Read("invalid/avif/sequence-fragmented").IsFragmented);
        Assert.Equal(2, Read("invalid/avif/two-meta-boxes").TopLevelBoxes.Count(box => box.Type == "meta"));
        Assert.Null(Read("invalid/avif/missing-pitm").PrimaryItemId);
        Assert.Null(Read("invalid/avif/missing-primary-item").PrimaryItem);
        Assert.Null(Read("invalid/avif/missing-ispe").PrimaryItem!.Size);
        Assert.Null(Read("invalid/avif/missing-av1c").PrimaryItem!.Configuration);
        Assert.Equal("iden", Read("invalid/avif/derived-iden").PrimaryItem!.Type);
        Assert.Equal("iovl", Read("invalid/avif/derived-iovl").PrimaryItem!.Type);
        Assert.Null(Read("invalid/avif/clap-fractional").PrimaryItem!.CleanAperture!.GetRectangle(8, 8));
        Assert.Equal(14, Read("invalid/avif/matrix-ictcp").PrimaryItem!.Nclx!.MatrixCoefficients);
        Assert.Contains(Read("invalid/avif/essential-unknown-property").PrimaryItem!.Associations, association => association is { IsEssential: true, Property.Type: "zzzz" });
        var alpha = Read("invalid/avif/alpha-different-size");
        Assert.NotEqual(alpha.PrimaryItem!.Size, alpha.AlphaItem!.Size);
        Assert.False(Read("invalid/avif/ftyp-without-avif-brand").HasBrand("avif"));
        Assert.Equal(1, Read("invalid/avif/sequence-edit-list-offset").Tracks[0].EditList!.Entries[0].MediaTime);
        Assert.All(Read("invalid/avif/sequence-no-av1-track").Tracks, track => Assert.Equal("hvc1", track.SampleEntryType));
        Assert.Equal(3, Read("invalid/avif/grid-tile-count-mismatch").GetGridTiles(Read("invalid/avif/grid-tile-count-mismatch").PrimaryItem!).Count);

        // Image sequences: the edit ends when the second image of three starts; the sample entry declares ICtCp; a
        // metadata item of the track, or of the meta box of the file that precedes the moov box, is located after the end
        // of the file
        var edit = Read("invalid/avif/sequence-edit-ends-before-last-image").ColorTrack!;
        Assert.Equal(3, edit.Samples.Count);
        Assert.Equal((ulong)edit.Samples[0].Duration, edit.EditList!.Entries[0].SegmentDuration);
        Assert.True(edit.EditList.Entries[0].SegmentDuration < (ulong)(edit.Samples[0].Duration + edit.Samples[1].Duration));
        Assert.Equal(edit.Timescale, Read("invalid/avif/sequence-edit-ends-before-last-image").MovieTimescale);
        Assert.Equal(14, Read("invalid/avif/sequence-matrix-ictcp").ColorTrack!.Nclx!.MatrixCoefficients);
        foreach (var id in new[] { "invalid/avif/sequence-track-metadata-outside-file", "invalid/avif/sequence-file-metadata-outside-file" })
        {
            var file = Read(id);
            var (exif, xmp) = file.FindSequenceMetadata();
            var item = exif ?? xmp;
            Assert.NotNull(item);
            Assert.Equal(id.Contains("track", StringComparison.Ordinal), file.ColorTrack!.HasMeta);
            Assert.True(item.Extents[0].Offset > GoldenCorpus.Default.Get(id).ReadInput().Length);
            Assert.Throws<InvalidDataException>(() => file.ReadItemData(item));
        }

        // A grid whose second tile declares another rotation than the grid and the first tile
        var transformed = Read("invalid/avif/grid-tile-transform-differs");
        var transformedTiles = transformed.GetGridTiles(transformed.PrimaryItem!);
        Assert.Equal(transformed.PrimaryItem!.Orientation, transformedTiles[0].Orientation);
        Assert.NotEqual(transformed.PrimaryItem!.Orientation, transformedTiles[1].Orientation);

        // Operating points and layers: what each file selects, and what its bitstream has
        var missingPoint = Read("invalid/avif/a1op-missing-operating-point");
        Assert.Equal(1, missingPoint.PrimaryItem!.OperatingPoint);
        Assert.HasCount(1, ReferenceObuStream.ReadOperatingPoints(missingPoint.ReadItemData(missingPoint.PrimaryItem)));
        var beyondPoints = Read("invalid/avif/a1op-beyond-operating-points");
        Assert.Equal(3, beyondPoints.PrimaryItem!.OperatingPoint);
        Assert.HasCount(3, ReferenceObuStream.ReadOperatingPoints(beyondPoints.ReadItemData(beyondPoints.PrimaryItem)));
        var missingLayer = Read("invalid/avif/lsel-missing-layer");
        Assert.Equal(1, missingLayer.PrimaryItem!.LayerSelector);
        Assert.Equal([0], ReferenceObuStream.GetSpatialLayers(missingLayer.ReadItemData(missingLayer.PrimaryItem)).ToArray());
        var beyondLayers = Read("invalid/avif/lsel-beyond-layers");
        Assert.Equal(3, beyondLayers.PrimaryItem!.LayerSelector);
        Assert.Equal([0, 1, 2], ReferenceObuStream.GetSpatialLayers(beyondLayers.ReadItemData(beyondLayers.PrimaryItem)).ToArray());
        Assert.Equal(4, Read("invalid/avif/lsel-out-of-range").PrimaryItem!.LayerSelector);
        var outside = Read("invalid/avif/lsel-outside-operating-point");
        Assert.Equal((2, 1), (outside.PrimaryItem!.OperatingPoint, outside.PrimaryItem.LayerSelector));
        Assert.Equal(0x101, ReferenceObuStream.ReadOperatingPoints(outside.ReadItemData(outside.PrimaryItem))[2]);
        Assert.Contains(1, ReferenceObuStream.GetSpatialLayers(outside.ReadItemData(outside.PrimaryItem)));
        var sizeMismatch = Read("invalid/avif/lsel-layer-size-mismatch");
        Assert.Equal(0, sizeMismatch.PrimaryItem!.LayerSelector);
        Assert.Equal(sizeMismatch.PrimaryItem.Size, Read("avif/layered-progressive-444-10bit").PrimaryItem!.Size);
        Assert.NotEqual(sizeMismatch.PrimaryItem.Size, Read("avif/layered-lsel-0-smaller").PrimaryItem!.Size);
        Assert.Equal(Convert.ToHexString(sizeMismatch.ReadItemData(sizeMismatch.PrimaryItem)), Convert.ToHexString(Read("avif/layered-lsel-0-smaller").ReadItemData(Read("avif/layered-lsel-0-smaller").PrimaryItem!)));
        Assert.Equal(("grid", 0, null), (Read("invalid/avif/lsel-on-grid").PrimaryItem!.Type, Read("invalid/avif/lsel-on-grid").PrimaryItem!.LayerSelector, Read("invalid/avif/lsel-on-grid").PrimaryItem!.OperatingPoint));
        Assert.Equal(("grid", null, 1), (Read("invalid/avif/a1op-on-grid").PrimaryItem!.Type, Read("invalid/avif/a1op-on-grid").PrimaryItem!.LayerSelector, Read("invalid/avif/a1op-on-grid").PrimaryItem!.OperatingPoint));

        // The files the independent reader rejects too
        foreach (var id in new[] { "invalid/avif/truncated-meta", "invalid/avif/box-size-too-small", "invalid/avif/child-box-exceeds-parent", "invalid/avif/sequence-track-meta-malformed" })
        {
            Assert.Throws<InvalidDataException>(() => Read(id));
        }

        static ReferenceAvif Read(string id) => ReferenceAvif.Parse(GoldenCorpus.Default.Get(id).ReadInput());
    }

    private static (int Max, double Mean, string Location) Measure(RawPixelBuffer expected, RawPixelBuffer actual)
    {
        Assert.Equal(expected.Layout, actual.Layout);
        Assert.Equal((expected.Width, expected.Height), (actual.Width, actual.Height));
        var channels = expected.Layout.ChannelCount;
        var max = 0;
        var sum = 0L;
        var count = 0;
        var location = "(none)";
        for (var y = 0; y < expected.Height; y++)
        {
            for (var x = 0; x < expected.Width; x++)
            {
                for (var c = 0; c < channels; c++)
                {
                    var difference = Math.Abs(expected.GetSample(x, y, c) - actual.GetSample(x, y, c));
                    if (c == 3)
                    {
                        Assert.Equal(0, difference); // alpha is exact
                        continue;
                    }

                    sum += difference;
                    count++;
                    if (difference > max)
                    {
                        max = difference;
                        location = string.Create(CultureInfo.InvariantCulture, $"({x}, {y}) channel {c}");
                    }
                }
            }
        }

        return (max, (double)sum / count, location);
    }
}
